INSERT INTO strategies VALUES(1,'viscale','viscale','{"rules":{"icpKeys":["B2B-1","B2B-2","B2B-3","B2C","UNI","BK"],"hashtags":["#viscale","#Vertriebssystem","#HubSpot","#Mittelstand"],"signoff":"das viscale-Team","editorialPlanTitle":"Redaktionsplan \u00b7 viscale","defaultOwner":"viscale","clusters":[{"key":"cluster_1","code":"E3-02","name":"Vertrieb h\u00e4ngt an Personen","match":"person|vertriebsleiter|kopf"},{"key":"cluster_2","code":"E3-01","name":"Blindflug im Forecast","match":"forecast|pipeline|signen|unterschreiben"},{"key":"cluster_3","code":"E3-03","name":"Leads versickern unbemerkt","match":"lead|versick|nachverfolg"},{"key":"cluster_4","code":"E3-05","name":"Wachstum wird teurer statt effizienter","match":"teuer|effizienz|cac|wachs"},{"key":"cluster_5","code":"E3-06","name":"Datenchaos & fehlende Datenhygiene","match":"daten|property|chaos|hygiene"},{"key":"cluster_6","code":"E1-02","name":"KI-Druck ohne Fundament","match":"ki|ai|breeze"}],"defaultClusterKey":"cluster_2","icpGuesser":[{"icp":"BK","match":"bestand|renewal|adoption|retainer"},{"icp":"UNI","match":"uni|hochschule|forschung"},{"icp":"B2C","match":"b2c|consumer|ecommerce"},{"icp":"B2B-2","match":"forecast|pipeline|head of sales|sales"},{"icp":"B2B-3","match":"crm|chaos|struktur|hubspot"}],"defaultIcp":"B2B-1","harvestCandidatePattern":"crm|forecast|lead|hubspot|pipeline","forbiddenPatterns":["!","beste[nrsm]?","einzigartig(?:e|er|es|en)?","revolution[a\u00e4]r(?:e|er|es|en)?","dein vertrieb kann mehr","verbessere deinen vertrieb"],"genericBkPatterns":["wir freuen uns","spannend(?:e|er|es|en)?","interessant(?:e|er|es|en)?","bucht jetzt","demo anfragen"],"toneLabel":"viscale-Tonalit\u00e4tsregeln","monitoring":{"gaps":["B2B-2 Forecast-Beweislast wird im Markt meist nur oberfl\u00e4chlich adressiert.","Niemand besetzt aktuell die Kombination aus HubSpot-Mechanismus und F\u00fchrungslogik konsequent."],"gapLine":"L\u00fccken f\u00fcr viscale herausarbeiten","toneGapHint":"Danach L\u00fccken ge