INSERT INTO personas VALUES(1,1,'Stefan Berger','Vertriebsleiter Mittelstand (B2B-2)','direkt, ergebnisorientiert, skeptisch gegenüber Buzzwords','["Forecast-Genauigkeit","Pipeline-Transparenz","Vertriebsf\u00fchrung","HubSpot"]',NULL,1,'2026-08-30 17:37:57','2026-08-30 17:37:57','["Mein Forecast ist Bauchgef\u00fchl, kein System","Mein Team verkauft, aber ich sehe nicht warum","Pipeline-Reviews sind Verhandlung, nicht Analyse"]','["direkt","analytisch","provokant"]','Führungskraft, die Forecast-Sicherheit durch System statt Heldentaten will',NULL,'["Blindflug im Forecast","Vertrieb h\u00e4ngt an Personen"]','["datengetrieben","praxisnah","keine Floskeln"]');
INSERT INTO personas VALUES(2,1,'Julia Mantel','Geschäftsführerin B2B-SaaS (B2B-1)','strategisch, zahlengetrieben, ungeduldig mit Ausreden','["CAC","Skalierung","Vertriebseffizienz","Prozesse"]',NULL,1,'2026-08-30 17:37:57','2026-08-30 17:37:57','["Wachstum wird teurer statt effizienter","Ich kaufe keine Tools, ich kaufe Ergebnisse","Mein Vertrieb skaliert nicht mit"]','["strategisch","klartext"]','Entscheiderin, die CAC und Effizienz im Blick hat',NULL,'["Wachstum wird teurer statt effizienter","Leads versickern unbemerkt"]','["ROI-fokussiert","kurz","klar"]');
INSERT INTO personas VALUES(3,1,'Markus Held','RevOps / CRM-Verantwortlicher (B2B-3)','technisch-nüchtern, prozessaffin, genervt von Datenchaos','["Datenhygiene","CRM-Prozesse","HubSpot-Properties","KI-Readiness"]',NULL,1,'2026-08-30 17:37:57','2026-08-30 17:37:57','["Unsere CRM-Daten sind ein Friedhof","Ohne Datenhygiene ist jede KI-Strategie Theater","Properties pflegt bei uns niemand"]','["n\u00fcchtern","pr\u00e4zise"]','Operativer Enabler, der Datenchaos und KI-Druck ohne Fundament beendet',NULL,'["Datenchaos & fehlende Datenhygiene","KI-Druck ohne Fundament"]','["how-to","konkret","strukturiert"]');
