INSERT INTO content_strategies VALUES(1,1,'brand_voice','{"perspective":"du","tone":["direkt","analytisch","leicht provokant"],"sentence_style":"kurze Haupts\u00e4tze, aktiv, keine Schachtels\u00e4tze","forbidden_words":["revolution\u00e4r","game-changer","einzigartig","beste L\u00f6sung","f\u00fchrend","synergie"],"forbidden_patterns":["!","wir ","uns ","ich ","unser"],"rules":["Keine Ausrufezeichen","Kein wir\/uns\/ich \u2014 immer du\/dein Team","Keine Superlative ohne Beleg","Jede Behauptung braucht Mechanismus oder Zahl","Keine Buzzwords \u2014 konkrete Begriffe statt Marketing-Sprech"]}',1,'2026-08-30 18:56:28','2026-08-30 18:56:28');
INSERT INTO content_strategies VALUES(2,1,'channel_rules','{"linkedin_post":{"word_count":{"min":150,"max":250},"structure":["hook","pain","mechanism","proof","implication","cta","hashtags"],"hook_max_words":8,"hashtag_count":{"min":3,"max":5},"cta_style":"soft \u2014 Frage oder Einladung, kein Jetzt-Demo-buchen","line_breaks":"Leerzeile nach Hook und zwischen Abs\u00e4tzen (Scanbarkeit)"},"ad_copy":{"primary_text_max_chars":125,"headline_max_chars":40,"structure":["pain","mechanism","proof","cta"],"cta_style":"direkt, eine Handlung"},"newsletter_acquisition":{"subject_line_rule":"Neugier wecken, max 50 Zeichen, kein Clickbait","preview_text_rule":"erg\u00e4nzt Subject, max 90 Zeichen","body_paragraphs":{"min":3,"max":4},"cta_count":1},"landing_page_headlines":{"headline_max_chars":60,"rule":"Outcome- oder Mechanismus-Frame, kein Feature-Gerede"},"newsletter_bk":{"tone":"Bestandskunden \u2014 partnerschaftlich, kein Verkaufsdruck","structure":["einordnung","konkreter_schritt","angebot_dialog"]}}',1,'2026-08-30 18:56:28','2026-08-30 18:56:28');
INSERT INTO content_strategies VALUES(3,1,'post_templates','{"contrarian_take":{"label":"Contrarian Take","beschreibung":"Gegen den Mainstream \u2014 alle sagen X, Realit\u00e4t ist Y","hook_pattern":"Behauptung die widerspricht, max 8 W\u00f6rter","struktur":["These gegen Mainstream","Warum der Mainstream irrt (Mechanismus)","Beleg","Was das hei\u00dft","Soft CTA"],"best_for":["B2B-2","B2B-3"],"beispiel_hook":"CRM-Automatisierung macht euren Vertrieb schlechter."},"data_drop":{"label":"Data Drop","beschreibung":"\u00dcberraschende Zahl + Einordnung","hook_pattern":"Zahl + \u00fcberraschende Ursache","struktur":["Zahl\/Fakt","Warum das \u00fcberrascht","Mechanismus dahinter","Konsequenz","Soft CTA"],"best_for":["B2B-1","B2B-2"],"beispiel_hook":"73% der Forecasts liegen daneben. Der Markt ist unschuldig."},"mistake_post":{"label":"Mistake Post","beschreibung":"Die N h\u00e4ufigsten Fehler bei X","hook_pattern":"N Fehler bei [Thema], die wir oft sehen","struktur":["Fehler 1 + Folge","Fehler 2 + Folge","Fehler 3 + Folge","Wie man es richtig macht","Soft CTA"],"best_for":["B2B-3","BK"],"beispiel_hook":"3 Fehler bei der HubSpot-Property-Hygiene, die wir oft sehen."},"framework":{"label":"Framework \/ Modell","beschreibung":"Eigenes Denkmodell oder Methode teilen","hook_pattern":"Unser N-Stufen-Modell f\u00fcr X","struktur":["Problem","Modell-\u00dcbersicht","Stufe 1-3 kurz","Ergebnis bei Anwendung","Soft CTA"],"best_for":["B2B-1","B2B-2"],"beispiel_hook":"Unser 3-Stufen-Modell f\u00fcr Datenhygiene."}}',1,'2026-08-30 18:56:28','2026-08-30 18:56:28');
INSERT INTO content_strategies VALUES(4,1,'icp_channel_mapping','{"B2B-1":{"channels":["linkedin_post","newsletter_acquisition"],"patterns":["data_drop","framework"],"funnel":"ToFu"},"B2B-2":{"channels":["linkedin_post","ad_copy"],"patterns":["contrarian_take","data_drop"],"funnel":"MoFu"},"B2B-3":{"channels":["linkedin_post","newsletter_acquisition"],"patterns":["mistake_post","contrarian_take"],"funnel":"MoFu"},"BK":{"channels":["newsletter_bk"],"patterns":["mistake_post"],"funnel":"Retention"}}',1,'2026-08-30 18:56:28','2026-08-30 18:56:28');
